import numpy as np, pandas as pd
train = pd.read_csv('train.csv')
X = train.drop(columns=['target']).to_numpy(float)
y = train['target'].to_numpy(int)

rng=np.random.default_rng(0)
idx=rng.permutation(len(y)); split=int(0.8*len(y)); tr,va=idx[:split],idx[split:]
Xtr,Xva=X[tr],X[va]; ytr,yva=y[tr],y[va]


def gini_counts(pos, total):
    if total <= 0:
        return 0.0
    p = pos / total
    return 1.0 - p*p - (1.0-p)*(1.0-p)


def best_split(X, y, feature_ids):
    base = gini_counts(y.sum(), len(y))
    best_gain = -1.0
    best = None
    for j in feature_ids:
        values = X[:, j]
        for t in np.unique(np.quantile(values, np.linspace(0.1, 0.9, 9))):
            left = values <= t
            nl = left.sum(); nr = len(y) - nl
            if nl < 30 or nr < 30:
                continue
            yl = y[left]; yr = y[~left]
            gain = base - (nl/len(y))*gini_counts(yl.sum(), nl) - (nr/len(y))*gini_counts(yr.sum(), nr)
            if gain > best_gain:
                best_gain = gain
                best = (j, float(t), left)
    return best


def fit_tree(X, y, rng, max_depth=2, mtry=10):
    def build(Xn, yn, depth):
        pred = int(yn.mean() >= 0.5)
        if depth == max_depth or len(yn) < 60 or yn.min() == yn.max():
            return ('leaf', pred)
        feats = rng.choice(Xn.shape[1], size=min(mtry, Xn.shape[1]), replace=False)
        split = best_split(Xn, yn, feats)
        if split is None:
            return ('leaf', pred)
        j, t, left = split
        return ('node', j, t, build(Xn[left], yn[left], depth+1), build(Xn[~left], yn[~left], depth+1))
    return build(X, y, 0)


def predict_tree(tree, X):
    out = np.empty(len(X), dtype=int)
    def rec(node, idx):
        if node[0] == 'leaf':
            out[idx] = node[1]
            return
        _, j, t, left_node, right_node = node
        mask = X[idx, j] <= t
        rec(left_node, idx[mask])
        rec(right_node, idx[~mask])
    rec(tree, np.arange(len(X)))
    return out

for n_trees in [5, 15, 31]:
    votes = np.zeros(len(yva), dtype=float)
    for i in range(n_trees):
        boot = rng.integers(0, len(ytr), size=len(ytr))
        tree = fit_tree(Xtr[boot], ytr[boot], np.random.default_rng(i), max_depth=3, mtry=10)
        votes += predict_tree(tree, Xva)
    pred = (votes >= (n_trees/2)).astype(int)
    print(n_trees, float((pred == yva).mean()))
